var css = "/* Decorative celestial skin. Official CSS modules stay untouched. */\n\n:root {\n  --dsh-celestial-gold: #ae843b;\n  --dsh-celestial-panel: #fbf7ec;\n  --dsh-celestial-base: #f3ead3;\n  --dsh-font-display: 'Songti SC', STSong, 'Noto Serif CJK SC', SimSun, serif;\n}\n\nbody[data-ds-dark-theme] {\n  --dsh-celestial-gold: #c9a254;\n  --dsh-celestial-panel: #101f34;\n  --dsh-celestial-base: #071729;\n}\n\n/* ---------------------------------------------------------------------------\n   Make the backdrop visible without touching any shell stylesheet.\n\n   The desktop shell paints `--dsw-alias-bg-base` as an opaque fill on both\n   AppFrame `.frame` and ConversationRoot `.root`. Those two boxes sit above\n   the artwork, so a tinted token still reads as an empty panel. The Electron\n   window itself is also opaque, so the token cannot be fully transparent or\n   the stock `#181818` chrome shows through the gaps.\n\n   `body` keeps the solid celestial base. The token used by the two full-bleed\n   shells is transparent, which lets the stage (a body child, behind `#root`)\n   show through. `!important` outranks the theme presenter's inline token\n   writes; the shell never marks these properties important.\n   --------------------------------------------------------------------------- */\nbody {\n  --dsw-alias-bg-base: transparent !important;\n  background-color: var(--dsh-celestial-base) !important;\n  background-image: var(--dsh-celestial-light-image) !important;\n  background-position: left center !important;\n  background-repeat: no-repeat !important;\n  background-size: cover !important;\n}\n\nbody[data-ds-dark-theme] {\n  --dsw-alias-bg-base: transparent !important;\n  background-color: var(--dsh-celestial-base) !important;\n  background-image: var(--dsh-celestial-dark-image) !important;\n  background-position: 68% center !important;\n  background-repeat: no-repeat !important;\n  background-size: cover !important;\n}\n\n/* The frame and the conversation column are the two boxes that hide the\n   stage. Attribute selectors survive CSS-module hashes. */\n[data-sidebar-collapsed],\n[data-details-collapsed],\n[data-dragging],\n[data-phase='hero'],\n[data-phase='active'],\n[data-phase='settling'] {\n  background: transparent !important;\n  background-color: transparent !important;\n}\n\n/* Active transcripts keep the same full composition as the landing screen.\n   The reading surface belongs to the scrollport, which starts below the\n   session header: the header stays on the sky, and the transcript gets one\n   solid panel instead of a fade that cuts through a planet. */\n[data-phase='active'] [data-conversation-scroll]::before,\n[data-phase='settling'] [data-conversation-scroll]::before {\n  content: '';\n  position: absolute;\n  z-index: 0;\n  inset: 0;\n  pointer-events: none;\n  background-color: var(--dsh-celestial-base);\n  border-top: 1px solid color-mix(in srgb, var(--dsh-celestial-gold) 28%, transparent);\n}\n\n[data-phase='active'] [data-conversation-scroll] > *,\n[data-phase='settling'] [data-conversation-scroll] > * {\n  position: relative;\n  z-index: 1;\n}\n\n/* Document preview lives in the same window, but its page surface is opaque\n   and reads `--dsw-alias-bg-document-preview` directly. The token override\n   covers the steady state; these important declarations also win while the\n   presenter is still writing the stock palette during the first frame. */\nbody {\n  --dsw-alias-bg-document-preview: var(--dsh-celestial-panel) !important;\n  --dsw-alias-label-document-preview: #5c5348 !important;\n}\n\nbody[data-ds-dark-theme] {\n  --dsw-alias-bg-document-preview: var(--dsh-celestial-base) !important;\n  --dsw-alias-label-document-preview: #c7bda9 !important;\n}\n\n[data-dsh-celestial-host],\n[data-dsh-celestial-stage] {\n  position: fixed;\n  inset: 0;\n  z-index: 0;\n  overflow: hidden;\n  pointer-events: none !important;\n  /* The artwork sits at z-index 0; the shell stacks two full-bleed\n     `--dsw-alias-bg-base` containers above it in the steady state (AppFrame\n     `.frame` and ConversationRoot `.root`; `.boot` only exists during load), so\n     the visible transmission is the product of both alphas.\n\n     At 30% that product was (1-0.30)^2 \u2248 49%, and the dark-theme artwork is a\n     deep-navy sky \u2014 49% of an already-dark image reads as \"no backdrop at all\"\n     on screen. 12% leaves \u224877%, which is what actually makes it legible.\n     Verified against a live screenshot at 15:38 rather than by arithmetic\n     alone: the art was reaching the eye all along, just far too dim. */\n  --dsh-celestial-art-opacity-light: 0.72;\n  /* Dark mode: the artwork is a deep-navy sky, so the two stacked\n     `--dsw-alias-bg-base` layers above it cost the most here \u2014 and the loss is\n     worst on narrow windows, where `background-size: cover` has to crop and\n     there is simply less lit area to survive. 0.95 keeps the gold linework\n     clearly readable at the default window size without the night sky going\n     flat. Overridden per width by the media queries at the end of this sheet. */\n  --dsh-celestial-art-opacity-dark: 0.95;\n  --dsh-celestial-particle-opacity-light: 0.16;\n  --dsh-celestial-particle-opacity-dark: 0.2;\n  /* The vignette paints the panel colour (deep navy in dark mode) over the\n     centre so text stays readable. Heavy values here fight the artwork: at the\n     old 0.42 / 0.82 pair, dark mode read as an empty screen because the mask\n     was dark-on-dark. Reduced so the backdrop survives while the reading area\n     keeps its contrast. */\n  --dsh-celestial-vignette-opacity: 0.24;\n  --dsh-celestial-reading-x: 60%;\n  --dsh-celestial-particle-mask: radial-gradient(\n    ellipse 40% 72% at var(--dsh-celestial-reading-x) 50%,\n    transparent 0%,\n    rgb(0 0 0 / 0.12) 48%,\n    rgb(0 0 0 / 0.72) 78%,\n    #000 100%\n  );\n}\n\n[data-dsh-celestial-stage][data-hero] {\n  --dsh-celestial-art-opacity-light: 0.78;\n  /* The hero selector outranks the narrower-window rules below. Keep the\n     actual landing screen bright, rather than silently falling back to 0.9. */\n  --dsh-celestial-art-opacity-dark: 0.98;\n  --dsh-celestial-particle-opacity-light: 0.42;\n  --dsh-celestial-particle-opacity-dark: 0.5;\n  /* The composer has its own opaque surface; a second navy mask over the\n     artwork only hides the planets without improving text readability. */\n  --dsh-celestial-vignette-opacity: 0;\n  --dsh-celestial-reading-x: calc(50% + 64px);\n  --dsh-celestial-particle-mask: radial-gradient(\n    ellipse 390px 235px at var(--dsh-celestial-reading-x) 53%,\n    transparent 0%,\n    rgb(0 0 0 / 0.08) 46%,\n    rgb(0 0 0 / 0.68) 76%,\n    #000 100%\n  );\n}\n\n[data-dsh-celestial-art],\n[data-dsh-celestial-vignette] {\n  position: absolute;\n  inset: 0;\n  pointer-events: none;\n}\n\n[data-dsh-celestial-art] {\n  /* `contain` letterboxes the art: it fits the whole 1600x900 source inside the\n     element, so on a wider-than-16:9 window there are empty bands left and\n     right. The left band is harmless (the sidebar covers it), but the right band\n     exposes bare background to the right of the drawing's own border, which\n     reads as \"the picture just stops\".\n\n     `cover` scales the art to fill both axes. Light mode retains left\n     alignment. In the real dark desktop window, that alignment hid the sun\n     beneath the sidebar, so dark mode shifts its art into the workspace.\n     `contain` + `left` shrank the canvas and exposed an empty right band. */\n  background-position: left center;\n  background-repeat: no-repeat;\n  background-size: cover;\n  transition: opacity 300ms var(--ds-ease-in-out, ease);\n}\n\n[data-dsh-celestial-art='light'] {\n  background-image: var(--dsh-celestial-light-image);\n  opacity: var(--dsh-celestial-art-opacity-light);\n}\n\n[data-dsh-celestial-art='dark'] {\n  background-image: var(--dsh-celestial-dark-image);\n  opacity: 0;\n}\n\nbody[data-ds-dark-theme] [data-dsh-celestial-art='light'] {\n  opacity: 0;\n}\n\nbody[data-ds-dark-theme] [data-dsh-celestial-art='dark'] {\n  opacity: var(--dsh-celestial-art-opacity-dark);\n  /* In the actual desktop window, left alignment put the sun beneath the\n     sidebar. Shift the composition into the conversation area; the empty\n     strip at the left remains covered by the sidebar. */\n  background-position: 68% center;\n  /* Lift the gold linework away from the similarly coloured navy panel. */\n  filter: brightness(1.35) contrast(1.12) saturate(1.1);\n}\n\n/* The transcript keeps the full composition, but the session header is only\n   a short band above the reading surface. Nudge the picture down so that\n   band lands on open sky instead of slicing through Jupiter. */\nbody[data-ds-dark-theme] [data-dsh-celestial-stage][data-transcript] [data-dsh-celestial-art='dark'] {\n  background-position: 68% 132px;\n}\n\n[data-dsh-celestial-vignette] {\n  background: radial-gradient(\n    ellipse 370px 220px at var(--dsh-celestial-reading-x) 53%,\n    color-mix(in srgb, var(--dsh-celestial-base) 92%, transparent) 0%,\n    color-mix(in srgb, var(--dsh-celestial-base) 72%, transparent) 42%,\n    transparent 78%\n  );\n  opacity: var(--dsh-celestial-vignette-opacity);\n}\n\n[data-dsh-particle-field] {\n  position: absolute;\n  inset: 0;\n  z-index: 1;\n  display: block;\n  width: 100%;\n  height: 100%;\n  pointer-events: none;\n  opacity: var(--dsh-celestial-particle-opacity-light, 0.12);\n  -webkit-mask-image: var(--dsh-celestial-particle-mask);\n  mask-image: var(--dsh-celestial-particle-mask);\n  -webkit-mask-mode: alpha;\n  mask-mode: alpha;\n}\n\nbody[data-ds-dark-theme] [data-dsh-particle-field] {\n  opacity: var(--dsh-celestial-particle-opacity-dark, 0.16);\n}\n\n@media (prefers-reduced-motion: reduce) {\n  [data-dsh-celestial-art] {\n    transition: none;\n  }\n}\n\n#root {\n  position: relative;\n  z-index: 1;\n  background: transparent !important;\n}\n\n/* Desktop (not the browser) paints the whole window from the sidebar token:\n   `[data-windows-titlebar] .frame { background: var(--dsw-specific-sidebar-fill) }`.\n   The attribute lives on <html>. The frame's class is hashed per build, and an\n   unhashed wrapper sits between `#root` and the grid, so the selector walks\n   both levels. Without this the browser shows the sky and the desktop stays flat. */\n[data-windows-titlebar] #root > div,\n[data-windows-titlebar] #root > div > div {\n  background: transparent !important;\n  background-color: transparent !important;\n}\n\n[data-windows-titlebar] [class*='centerCol'] {\n  background: transparent !important;\n  background-color: transparent !important;\n}\n\n/* The sidebar column and the sidebar root both paint the same fill, so a\n   translucent token would stack into a nearly solid panel. Leave the fill\n   translucent for the inner surface and fade, and keep only one layer here. */\n[data-windows-titlebar] [class*='sidebarCol'] {\n  background: transparent !important;\n  background-color: transparent !important;\n}\n\n[data-dsh-celestial-chrome] {\n  position: fixed;\n  inset: 0;\n  z-index: 40;\n  pointer-events: none;\n}\n\n[data-dsh-window-titlebar] {\n  position: fixed;\n  inset: 0 0 auto;\n  z-index: 40;\n  height: var(--dsh-window-titlebar-height, 0px);\n  pointer-events: none;\n  background:\n    linear-gradient(\n      color-mix(in srgb, var(--dsh-celestial-gold) 42%, transparent),\n      color-mix(in srgb, var(--dsh-celestial-gold) 42%, transparent)\n    ) bottom / 100% 1px no-repeat,\n    color-mix(in srgb, var(--dsh-celestial-panel) 84%, transparent);\n  backdrop-filter: blur(12px) saturate(108%);\n}\n\n[data-dsh-window-drag-region] {\n  position: fixed;\n  top: var(--dsh-window-titlebar-y, 0px);\n  left: var(--dsh-window-titlebar-x, 0px);\n  z-index: 41;\n  width: var(--dsh-window-titlebar-width, 0px);\n  height: var(--dsh-window-titlebar-height, 0px);\n  pointer-events: auto;\n  user-select: none;\n  -webkit-app-region: drag;\n}\n\nh1, h2, .dsh-display {\n  font-family: var(--dsh-font-display);\n}\n\n/* ---------------------------------------------------------------------------\n   Narrow-window legibility.\n\n   The artwork is bright enough to read on a wide window, but the shell window\n   can be dragged down to a fairly tight size, and at those widths `cover` has\n   to crop harder \u2014 the lit left third of the composition takes up proportionally\n   more of the frame, the darker right-hand sky is the only thing left, and the\n   two `--dsw-alias-bg-base` layers above it then read as \"empty background\".\n\n   Raising the art's own opacity is the correct lever here: it costs nothing on\n   wide windows, darkens nothing (the art IS the dark colour), and keeps the\n   linework separable from the panel it is drawn against.\n\n   These rules apply to the non-hero view. The landing screen's more-specific\n   [data-hero] selector above sets its own dark opacity and vignette values.\n   --------------------------------------------------------------------------- */\n@media (max-width: 1560px) {\n  [data-dsh-celestial-stage] {\n    --dsh-celestial-art-opacity-dark: 0.97;\n  }\n}\n\n@media (max-width: 1280px) {\n  [data-dsh-celestial-stage] {\n    --dsh-celestial-art-opacity-dark: 0.98;\n    --dsh-celestial-vignette-opacity: 0;\n  }\n}\n";
